import AppKit
import SwiftUI

// MARK: - BrandLogoProvider
// High-resolution embedded official brand logos for media services.
// Zero network requests, zero file I/O overhead, instant 0ms rendering.
public enum BrandLogoProvider {
    private static var imageCache: [MediaService: NSImage] = [:]
    
    public static func logo(for service: MediaService) -> NSImage? {
        if let cached = imageCache[service] {
            return cached
        }
        guard let base64 = base64Data[service],
              let data = Data(base64Encoded: base64),
              let image = NSImage(data: data) else {
            return nil
        }
        imageCache[service] = image
        return image
    }
    
    private static let base64Data: [MediaService: String] = [
        .youtubeMusic: "",
        .primeVideo: "",
        .netflix: "",
        .youtube: "",
        .x: "",
        .spotify: "",
        .appleMusic: "",
        .disneyPlus: "",
        .soundcloud: "",
        .twitch: "",
    ]
}
